(window.GROUP_QUIZZES=window.GROUP_QUIZZES||{})["physical-diagnosis-2-exam-1-ocular-exam-quiz-version-2"]={"title":"Advanced Ocular History & Examination Quiz 2 — PD2 Exam 1","category":"Physical Diagnosis","exam":"Exam 1","sem":"fall-2026","questions":[{"q":"On the red-eye chart, which column has NO ocular discharge AND an unaffected pupil AND a clear cornea AND absent pain?","choices":["Glaucoma","Subconjunctival haemorrhage","Uncomplicated bacterial conjunctivitis","Acute iritis"],"answer":1,"exp":"Correct — every column reads negative, which is what makes it benign. — PD II Advanced Exam Ocular Lecture - Beck.pptx, Slide 48 (image only)"},{"q":"Acute, BILATERAL and painful symptoms should make you consider what?","choices":["Traumatic hyphaema","Thermal, radiation or chemical exposure","Retinal vascular occlusion","Simple glaucoma or a slowly maturing cataract"],"answer":1,"exp":"Correct — bilateral and painful points to an environmental exposure. — PD II Advanced Exam Ocular Lecture - Beck.pptx, Slide 16"},{"q":"A YELLOW sclera indicates what?","choices":["Anaemia","Liver disease","Osteogenesis imperfecta","Chronic ultraviolet exposure"],"answer":1,"exp":"Correct — jaundice. — PD II Advanced Exam Ocular Lecture - Beck.pptx, Slide 43"},{"q":"Which test is the vital sign of the eye?","choices":["Visual fields","Visual acuity","Intraocular pressure","Pupil reactivity"],"answer":1,"exp":"Correct — acuity testing is the vital sign of the eye. — PD II Advanced Exam Ocular Lecture - Beck.pptx, Slide 21"},{"q":"Eye pain ON EYE MOTION suggests what?","choices":["Acute narrow angle glaucoma","Optic neuritis","Corneal abrasion","Conjunctivitis"],"answer":1,"exp":"Correct — pain on movement points to optic neuritis. — PD II Advanced Exam Ocular Lecture - Beck.pptx, Slide 17"},{"q":"Purulent discharge suggests what?","choices":["Allergic conjunctivitis","Viral conjunctivitis","Dry eye","Bacterial infection"],"answer":3,"exp":"Correct — purulent discharge points to bacterial infection. — PD II Advanced Exam Ocular Lecture - Beck.pptx, Slide 19"},{"q":"Which two tests together make up the best confrontation field examination?","choices":["Tonometry and fundoscopy","The static finger wiggle test and the kinetic red target test","The swinging light test together with the cover-uncover test","The pinhole test and the Snellen chart"],"answer":1,"exp":"Correct — the static and kinetic tests together. — PD II Advanced Exam Ocular Lecture - Beck.pptx, Slide 53"},{"q":"What does the cover-uncover test reveal?","choices":["A slight muscle imbalance not otherwise seen","An afferent pupillary defect of the optic nerve","A refractive error","A field defect"],"answer":0,"exp":"Correct — that is what the test is for. — PD II Advanced Exam Ocular Lecture - Beck.pptx, Slide 67"},{"q":"A temporal field defect in one eye should prompt what?","choices":["Repeating acuity in the same eye","Measuring intraocular pressure","Testing for a nasal defect in the other eye","Immediate fundoscopy of the same eye only"],"answer":2,"exp":"Correct — a temporal defect in one eye should prompt testing for a nasal defect in the other. — PD II Advanced Exam Ocular Lecture - Beck.pptx, Slide 55"},{"q":"Which abbreviation refers to the RIGHT eye, and which to both?","choices":["OD is the left eye; OS is the right","OD is the right eye; OU is both eyes","OS is the right eye; OD is both eyes","OU is the right eye; OS is both eyes"],"answer":1,"exp":"Correct — Beck said these abbreviations are terms you must remember. — PD II Advanced Exam Ocular Lecture - Beck.pptx, Slide 49"},{"q":"Which pair of diagnoses must be differentiated because the latter can lead to death?","choices":["Episcleritis from scleritis","Cataract from glaucoma","Hordeolum from chalazion","Preseptal from orbital cellulitis"],"answer":3,"exp":"Correct — orbital cellulitis can be fatal. — PD II Advanced Exam Ocular Lecture - Beck.pptx, Slide 20"},{"q":"What does a HAZY cornea in a suspected abrasion suggest?","choices":["The abrasion is healing normally","The fluorescein was applied incorrectly","Raised intraocular pressure","Bacterial infection should be suspected"],"answer":3,"exp":"Correct — haziness points to infection. — PD II Advanced Exam Ocular Lecture - Beck.pptx, Slide 120"},{"q":"Eye pain WITH HEADACHE suggests what?","choices":["Acute narrow angle glaucoma","Temporal arteritis with jaw claudication","Optic neuritis","Conjunctivitis"],"answer":0,"exp":"Correct — headache with eye pain points to acute narrow angle glaucoma. — PD II Advanced Exam Ocular Lecture - Beck.pptx, Slide 17"},{"q":"What causes SENILE ptosis?","choices":["Weakened muscle, relaxed tissues, and the weight of herniated fat","Antibody blockade at the neuromuscular junction of the levator","Interruption of the sympathetic supply","Compression of the oculomotor nerve"],"answer":0,"exp":"Correct — weakened muscle, relaxed tissues, and the weight of herniated fat. — PD II Advanced Exam Ocular Lecture - Beck.pptx, Slide 29"},{"q":"HORIZONTAL diplopia — images side by side — points to a palsy of which cranial nerves?","choices":["Fourth or sixth","Second or seventh","Third or sixth","Third or fourth"],"answer":2,"exp":"Correct — and Beck called this slide very important to commit to memory. — PD II Advanced Exam Ocular Lecture - Beck.pptx, Slide 18"},{"q":"What should be documented if a patient cannot read the chart at all?","choices":["The acuity recorded at the patient's last optometry visit","An estimate in dioptres","Counting fingers, hand motion, or light perception","Simply 'unable to test'"],"answer":2,"exp":"Correct — counting fingers, hand motion, then light perception. — PD II Advanced Exam Ocular Lecture - Beck.pptx, Slide 49"},{"q":"What is chemosis?","choices":["Injection of the superficially visible vessels of the conjunctiva or sclera","Forward displacement of the eye in the orbit","Outward turning of the lower eyelid","Swelling and inflammation of the conjunctiva"],"answer":3,"exp":"Correct — swelling and inflammation of the conjunctiva. — PD II Advanced Exam Ocular Lecture - Beck.pptx, Slide 3"},{"q":"Nodular episcleritis is associated with which two systemic diseases?","choices":["Diabetes and hypertension","Graves disease, myasthenia gravis and thyroid orbitopathy","Sjögren syndrome and sarcoidosis","Rheumatoid arthritis and lupus erythematosus"],"answer":3,"exp":"Correct — rheumatoid arthritis and lupus erythematosus. — PD II Advanced Exam Ocular Lecture - Beck.pptx, Slide 47"},{"q":"Where does a chalazion usually point?","choices":["Inside the lid rather than on the lid margin","On the lid margin, right at the base of the lashes","At the medial canthus","At the lateral canthus"],"answer":0,"exp":"Correct — this is what distinguishes it from a hordeolum. — PD II Advanced Exam Ocular Lecture - Beck.pptx, Slide 33"},{"q":"On the red-eye chart, how is the PAIN of acute iritis described?","choices":["Moderate, aching, deep","Mild discomfort rather than pain","Severe, aching, deep","Absent"],"answer":0,"exp":"Correct — the chart's iritis column. — PD II Advanced Exam Ocular Lecture - Beck.pptx, Slide 48 (image only)"},{"q":"Which two structures are commonly left unexamined?","choices":["The eyelids and eyebrows","The lacrimal sac and puncta","The extraocular muscles","The cornea and the lens"],"answer":3,"exp":"Correct — 'failure to examine the cornea and lens' is on the list. — PD II Advanced Exam Ocular Lecture - Beck.pptx, Slide 20"},{"q":"On the red-eye comparison, which condition shows redness that is DIFFUSE and maximal peripherally, with vision unaffected?","choices":["Glaucoma","Corneal injury or infection","Conjunctivitis","Acute iritis"],"answer":2,"exp":"Correct — diffuse peripheral redness with preserved vision is the conjunctivitis column. — PD II Advanced Exam Ocular Lecture - Beck.pptx, Slide 48 (image only)"},{"q":"Entropion and ectropion both affect which eyelid?","choices":["Both lids equally","Neither — they affect the conjunctiva","The lower lid","The upper lid"],"answer":2,"exp":"Correct — the lower lid for both. — PD II Advanced Exam Ocular Lecture - Beck.pptx, Slide 3"},{"q":"Which immunisation status matters in eye trauma?","choices":["Pneumococcal","Hepatitis B","Tetanus","Influenza"],"answer":2,"exp":"Correct — tetanus status matters in eye trauma. — PD II Advanced Exam Ocular Lecture - Beck.pptx, Slide 15"},{"q":"Gradual, painless visual loss suggests what?","choices":["Vitreous haemorrhage","Chemical exposure","Simple glaucoma or cataract","Acute narrow angle glaucoma"],"answer":2,"exp":"Correct — gradual and painless points to glaucoma or cataract. — PD II Advanced Exam Ocular Lecture - Beck.pptx, Slide 16"},{"q":"Which two symptoms together suggest an allergic cause?","choices":["Foreign body sensation and reduced vision","Itching and excessive tearing","Deep pain and photophobia","Burning and purulent discharge"],"answer":1,"exp":"Correct — itching with excessive tearing points to allergy. — PD II Advanced Exam Ocular Lecture - Beck.pptx, Slide 12"},{"q":"Which cranial nerve appears in BOTH the horizontal and vertical diplopia patterns?","choices":["The third","The fourth","The sixth","The second"],"answer":0,"exp":"Correct — Beck's shortcut was 'three for both of those'. — Lecture recording, 26 August 2026"},{"q":"Where do xanthelasma plaques sit, and what should they prompt?","choices":["Along the NASAL portions of one or both eyelids — consider lipid disorders","Along the temporal portions of the lids — consider thyroid disease","At the lid margin — consider bacterial infection","On the bulbar conjunctiva — consider ultraviolet exposure"],"answer":0,"exp":"Correct — nasal position, and it should prompt a lipid check. — PD II Advanced Exam Ocular Lecture - Beck.pptx, Slide 34"},{"q":"On the red-eye comparison, which condition shows a fixed, mid-dilated pupil with severe pain and markedly reduced vision?","choices":["Acute angle-closure glaucoma","Bacterial conjunctivitis","Anterior uveitis (iritis)","Corneal abrasion or ulcer"],"answer":0,"exp":"Correct — a fixed mid-dilated pupil with severe pain and reduced vision is the angle-closure picture. — Lecture recording, 26 August 2026"},{"q":"Which examination comes FIRST in the suggested order?","choices":["Visual acuity","Direct ophthalmoscopy","Ocular pressure","Inspection"],"answer":3,"exp":"Correct — the order begins with inspection. — PD II Advanced Exam Ocular Lecture - Beck.pptx, Slide 21"}]};
